insert into public.revision_content (id, data, updated_at) values
  ('cards-1', $xxb${"theme":1,"cards":[{"id":"t1-01","q":"Quand et où est né Baden-Powell ?","a":"Le **22 février 1857**, à Londres.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-02","q":"Quel est le nom complet de B-P, et quel titre reçoit-il en 1929 ?","a":"Robert Stephenson Smyth Baden-Powell. En 1929, le roi George V le fait **Lord Baden-Powell of Gilwell**.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-03","q":"Quelles étaient les professions du père et de la mère de B-P ?","a":"Père : pasteur protestant et professeur de géométrie à Oxford. Mère : naturaliste (Henrietta Grace Smyth).","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-04","q":"Qui était le parrain de B-P ?","a":"Robert Stephenson, fils de l'inventeur de la locomotive.","src":"fiches-BP.pdf"},{"id":"t1-05","q":"Quelle carrière B-P a-t-il eue avant le scoutisme, et quand l'a-t-il quittée ?","a":"Militaire de **1876 à 1910**. Il démissionne en 1910 pour se consacrer entièrement au mouvement.","src":"fiches-BP.pdf, Bases du scoutisme.pdf"},{"id":"t1-06","q":"Quel épisode a rendu B-P célèbre, et pourquoi compte-t-il pour le scoutisme ?","a":"Le **siège de Mafeking** (guerre des Boers, 1899-1900). C'est là que B-P découvre l'enthousiasme et l'utilité des jeunes (les « cadets de Mafeking »).","src":"Bases du scoutisme.pdf"},{"id":"t1-07","q":"Donne les trois surnoms africains de B-P et leur sens.","a":"**M'hala Panzi** (Natal) : l'homme qui se couche pour tuer. **Kantakye** (Ashantis) : l'homme au grand chapeau. **Impeesa** (Matabélés) : le loup qui ne dort jamais.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-08","q":"Quels instruments jouait B-P, et quelle fut sa première collection ?","a":"Piano et violon. Sa première collection : un dessin fait à 3 ans (il adorait dessiner).","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-09","q":"Quand B-P épouse-t-il Olave Soames, et où se sont-ils rencontrés ?","a":"Le **30 octobre 1912**. Ils se sont rencontrés lors d'une croisière (aux Antilles).","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-10","q":"Combien d'enfants ont eu Olave et B-P ?","a":"Trois : **Peter** (1913, prénom d'après Peter Pan), **Heather** (1915) et **Betty** (1917).","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-11","q":"Pourquoi B-P a-t-il arrêté de fumer en entrant dans l'armée ?","a":"Trois raisons : l'économie, le goût (il fumait par habitude) et l'odorat, un sens précieux dans l'art du « scouting » que le tabac altère.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-12","q":"Combien de livres B-P a-t-il écrits ?","a":"**32** au cours de sa vie.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-13","q":"Que signifie le signe « fin de piste » sur la tombe de B-P, et où est-il enterré ?","a":"Il signifie « retourné à la maison ». B-P est mort le **8 janvier 1941** à **Nyeri (Kenya)**, à 83 ans.","src":"fiches-BP.pdf, Bases du scoutisme.pdf"},{"id":"t1-14","q":"Que se passe-t-il pour B-P en 1939 ?","a":"Il est mis en nomination pour le **prix Nobel de la paix**. Le prix n'est pas remis, la Seconde Guerre mondiale débutant cette année-là.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-15","q":"Que devient Olave en 1916 puis en 1930 ?","a":"1916 : elle remplace Agnès, sœur de B-P, chez les guides. 1930 : elle est choisie **Chef guide mondiale**.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-16","q":"Quels cadeaux les scouts du monde ont-ils offerts à B-P et Olave en 1913 et en 1929 ?","a":"1913 : une « Standard Landaulette ». 1929, au 3e Jamboree mondial : une Rolls-Royce baptisée **« Jam Roll »** (100 000 scouts ont donné un penny chacun).","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-17","q":"Quelles sont les dates exactes du premier camp scout, et où a-t-il eu lieu ?","a":"Du **29 juillet au 9 août 1907**, sur l'île de **Brownsea** (Angleterre).","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-18","q":"Combien de jeunes à Brownsea, et que faisaient-ils ?","a":"Une vingtaine de jeunes. Jeux d'observation, de traque et de poursuite ; secourisme, nœuds, brêlages, camping, cuisine au feu de camp.","src":"fiches-BP.pdf","note":"Âge des jeunes : 9 à 17 ans selon fiches-BP, 12 à 17 ans selon Quiz-BP."},{"id":"t1-19","q":"Quels noms ont reçu les premières patrouilles de l'histoire ?","a":"Les **loups, les taureaux, les courlis et les corbeaux**.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-20","q":"Qui utilisait l'île de Brownsea avant B-P ?","a":"Les pirates et les contrebandiers.","src":"fiches-BP.pdf, Quiz-BP.pdf"},{"id":"t1-21","q":"Quel livre de B-P est publié en 1908, et sous quelle forme ?","a":"**Scouting for Boys** (Éclaireurs), en six livraisons bimensuelles puis réunies en volume (éditeur Pearson).","src":"Bases du scoutisme.pdf, fiches-BP.pdf"},{"id":"t1-22","q":"Que se passe-t-il à Crystal Palace en 1909 ?","a":"Le premier rallye : B-P invite les éclaireurs à se rassembler, **10 000** viennent.","src":"Bases du scoutisme.pdf, Connaissance du mvt rallye dak23.pdf"},{"id":"t1-23","q":"Que rappellent 1914 et 1916 dans l'histoire du mouvement ?","a":"**1914** : création du louvetisme. **1916** : publication du Livre du louveteau.","src":"Connaissance du mvt rallye dak23.pdf"},{"id":"t1-24","q":"La Route : quelle date de création, et quel livre B-P écrit-il pour les routiers ?","a":"Création en **1918** (annale Rallye) ou **1919** (Bases du scoutisme). Livre : *La route du succès*, publié en **1922** selon l'annale Rallye.","src":"Connaissance du mvt rallye dak23.pdf, Bases du scoutisme.pdf","note":"Les sources ne s'accordent pas : à retenir avec la date de chaque source."},{"id":"t1-25","q":"Qu'est-ce que Gilwell, et qui a donné le parc au scoutisme ?","a":"Le camp de formation des chefs lancé en **1919**. Le parc a été donné au scoutisme par **M. MacLaren**.","src":"Bases du scoutisme.pdf"},{"id":"t1-26","q":"Où et quand a eu lieu le premier Jamboree mondial, et que se passe-t-il pour B-P ?","a":"À **Londres en 1920** (8 000 scouts de 34 pays). B-P est proclamé **Chef scout du monde**.","src":"Quiz-BP.pdf, Bases du scoutisme.pdf, fiches-BP.pdf"},{"id":"t1-27","q":"D'où vient le mot « jamboree », et à quel rythme ont lieu ces rassemblements ?","a":"D'un mot zoulou qui veut dire « ralliement ». Rassemblements internationaux tous les **4 ans**.","src":"Bases du scoutisme.pdf"},{"id":"t1-28","q":"Que sait-on du Jamboree de 1929 ?","a":"Il a eu lieu à **Birkenhead** (près de Liverpool), pour le 20e anniversaire, avec **50 000** scouts.","src":"Bases du scoutisme.pdf"},{"id":"t1-29","q":"Quelle est la date du premier Jamboree sur les ondes ?","a":"**1958**.","src":"Quiz-BP.pdf"},{"id":"t1-30","q":"Quels sont les trois degrés historiques du mouvement et leurs âges ?","a":"**Louveteaux** (8-11 ans), **éclaireurs** (12-17 ans), **routiers** (17 ans et plus).","src":"Bases du scoutisme.pdf","note":"Repères historiques du texte. Les âges peuvent différer dans les textes nationaux actuels."},{"id":"t1-31","q":"Les 15 éléments fondamentaux : quels sont les trois groupes de cinq ?","a":"Les **5 buts**, les **5 dimensions** et les **5 moteurs**.","src":"Bases du scoutisme.pdf"},{"id":"t1-32","q":"Cite les 5 buts du scoutisme (acronyme SSSDF).","a":"**S**anté, **S**ervice du prochain, **S**ens de Dieu, **D**ébrouillardise (sens du concret), **F**ormation du caractère.","src":"Bases du scoutisme.pdf"},{"id":"t1-33","q":"Cite les 5 dimensions du scoutisme.","a":"La nature et le camp, la patrouille, la règle du jeu (la loi scoute), le civisme (la B.A.), l'engagement (la promesse).","src":"Bases du scoutisme.pdf"},{"id":"t1-34","q":"Cite les 5 moteurs du scoutisme.","a":"L'intérêt, l'action, les responsabilités, le système des patrouilles, la CDH et le CDC.","src":"Bases du scoutisme.pdf"},{"id":"t1-35","q":"Que dit le texte sur le « sens de Dieu » comme but ?","a":"Il n'est pas en soi un but défini par B-P. Le but du scoutisme n'est pas de former de futurs prêtres, mais de bons citoyens.","src":"Bases du scoutisme.pdf"},{"id":"t1-36","q":"La promesse scoute est un triple engagement. Lequel ?","a":"**Être loyal, aider autrui, observer la loi scoute.** Engagement volontaire, pris sur l'honneur devant ses frères.","src":"Bases du scoutisme.pdf"},{"id":"t1-37","q":"Pourquoi la loi scoute n'est-elle pas un règlement avec sanctions ?","a":"C'est une série de « conseils de vie » proposés au jeune, qui choisit de faire de son mieux. Pas de sanction : une discussion pour l'aider à progresser.","src":"Bases du scoutisme.pdf"},{"id":"t1-38","q":"Combien d'articles compte la loi de B-P, et quel est le 11e ?","a":"**10 articles** écrits. Le 11e, non écrit : « **Le scout n'est pas un sot.** »","src":"Bases du scoutisme.pdf"},{"id":"t1-39","q":"D'où vient la devise « Sois prêt » ?","a":"Des initiales de B-P : **Be Prepared**.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx"},{"id":"t1-40","q":"Quelles qualités la devise exige-t-elle de l'éclaireur ?","a":"Le **sens des autres**, la **compétence**, l'**observation suivie du réflexe**.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx"},{"id":"t1-41","q":"Que signifie être prêt d'esprit et prêt de corps selon B-P ?","a":"**D'esprit** : s'être donné la discipline d'obéir et avoir pensé d'avance aux situations possibles. **De corps** : s'être rendu fort, actif, capable de faire au bon moment l'action qu'il faut.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx"},{"id":"t1-42","q":"La bonne action (B.A.) : quelle règle sur la récompense, et que faire si on l'oublie ?","a":"On n'accepte **jamais de récompense** (de l'argent, ce serait du travail payé). Si on l'oublie, on fait **deux bonnes actions le lendemain**.","src":"Bases du scoutisme.pdf"},{"id":"t1-43","q":"Que devient la B.A. à la meute, à la troupe et au clan ?","a":"Meute : un plaisir fait chaque jour. Troupe : un réflexe d'aider, service spontané. Clan : un service permanent dans la communauté.","src":"Bases du scoutisme.pdf"},{"id":"t1-44","q":"Décris le salut scout et ce que signifient ses éléments.","a":"Main droite, **trois doigts du milieu levés** (triple promesse ; franchise, dévouement, pureté), **pouce sur l'auriculaire** (le fort protège le faible).","src":"Bases du scoutisme.pdf"},{"id":"t1-45","q":"Pourquoi les scouts se serrent-ils la main gauche ?","a":"Elle est du côté du cœur, et un chef ashanti l'a tendue à B-P : les plus braves serrent la main gauche, en abandonnant leur bouclier.","src":"Bases du scoutisme.pdf, fiches-BP.pdf"},{"id":"t1-46","q":"Que signifie la fleur de lys, et que veut dire le trèfle ?","a":"La fleur de lys indique le **nord** sur les cartes : le scout sait toujours retrouver son chemin. Le **trèfle** est le symbole des guides.","src":"fiches-BP.pdf, Bases du scoutisme.pdf"},{"id":"t1-47","q":"Quel est l'appel scout, et quand le lance-t-on ?","a":"« Sont-ils là les éclaireurs, sont-ils là ? » Réponse : « Ils sont là les éclaireurs, ils sont là. » On le lance avant d'entrer dans un coin de patrouille ou au Kraal.","src":"Bases du scoutisme.pdf"},{"id":"t1-48","q":"Quelle est la taille d'une patrouille ?","a":"Historiquement **huit** (début du mouvement, Bases du scoutisme). Aujourd'hui **cinq à sept** (LE SCOUTISME).","src":"Bases du scoutisme.pdf, LE SCOUTISME.docx","note":"Contradiction entre sources : à confirmer avec le Manuel du CP en décembre."},{"id":"t1-49","q":"Qu'est-ce que « l'esprit scout » ?","a":"L'attitude qu'on doit avoir, balisée par la loi scoute : vivre scoutement partout et faire passer le bonheur des autres au moins autant que le sien.","src":"la devise, l'esprit et les éléments fondamentaux du scoutismes.docx"},{"id":"t1-50","q":"Qui a eu l'idée de créer les scouts au Sénégal, et en quelle année ?","a":"Le R.P. **Lecocq**, curé de Dakar (Sacré-Cœur), en **1931**. Naissance officieuse en décembre 1931.","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-51","q":"Quel jour et où les quatre premiers scouts du Sénégal ont-ils fait leur promesse ?","a":"Le **8 mai 1932**, dans la cour de l'**école Saint Michel** à Dakar (fête de Sainte Jeanne d'Arc).","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-52","q":"Qui sont les quatre premiers scouts du Sénégal ?","a":"Gabriel Sagna, Emmanuel Nunez, Georges Monteiro et Paul de Souza.","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-53","q":"Quelles sont les deux premières patrouilles du Sénégal et leurs chefs ?","a":"**Rats palmistes** (CP Gabriel Sagna, SP Paul de Souza) et **Iguanes** (CP Emmanuel Nunez, SP Georges Monteiro).","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-54","q":"Qui sont le chef de troupe et l'aumônier de la première troupe, et comment s'appelle-t-elle ?","a":"Troupe **Sainte Jeanne d'Arc**. Chef de troupe : **Léon Fabert** (jeune militaire du 6e RAC). Aumônier : **R.P. Doutremepuich**.","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-55","q":"À quel mouvement le scoutisme sénégalais est-il affilié en 1932 ?","a":"Aux **Scouts de France** (affiliation officielle en 1932).","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-56","q":"Quelles unités apparaissent après la première troupe, et quand les routiers ?","a":"Une meute, puis les troupes **René Caillé** et **Charles Foucault**. Les scouts aînés deviennent routiers en **1938**.","src":"Historique Scoutisme Senegal.pdf"},{"id":"t1-57","q":"Qui est le saint patron des éclaireurs, et quand le célèbre-t-on ?","a":"**Saint Georges**, le **23 avril**.","src":"Connaissance du mvt rallye dak23.pdf"},{"id":"t1-58","q":"Qu'est-ce que le carnet de preuves, et quelles sont ses 4 parties ?","a":"Le manuel-guide de l'éclaireur qui lui permet de progresser. Parties : **volontaire, engagé, technicien, animateur**.","src":"Connaissance du mvt rallye dak23.pdf, Livret Carnet de Preuves.pdf"},{"id":"t1-59","q":"Quelle est la plus haute distinction dans le scoutisme ?","a":"Le **Loup de bronze**.","src":"Connaissance du mvt rallye dak23.pdf","note":"Source unique (annale Rallye Dakar 2023)."},{"id":"t1-60","q":"Qui est le premier Sénégalais à avoir reçu le Loup de bronze ?","a":"**Albert Ndiaye**.","src":"Connaissance du mvt rallye dak23.pdf","note":"Source unique (annale Rallye Dakar 2023)."}]}$xxb$::jsonb, now()),
  ('fiche-1', $xxb${"theme":1,"titre":"Bases et histoire","intro":"Construite à partir des documents du dossier Bases Générales et du dossier Troupe. Chaque section indique ses sources.","sections":[{"h":"Baden-Powell en repères","items":["**22 février 1857**, Londres. Père : pasteur protestant et professeur de géométrie à Oxford. Mère : naturaliste. Militaire de **1876 à 1910**.","**Brownsea, du 29 juillet au 9 août 1907** : une vingtaine de jeunes. Premières patrouilles : **loups, taureaux, courlis, corbeaux**. Jeux d'observation et de traque, secourisme, nœuds, camping, cuisine au feu de camp.","**1908** : *Scouting for Boys* (Éclaireurs). **1909** : premier rallye à Crystal Palace (10 000 éclaireurs). **1910** : B-P quitte l'armée.","**1912** : mariage avec Olave Soames (30 octobre), trois enfants : Peter, Heather, Betty. **1914** : création du louvetisme. **1916** : Livre du louveteau.","**1919** : camp de formation des chefs de Gilwell. **1920** : premier Jamboree mondial à Londres, B-P proclamé Chef scout du monde. **1922** : *La route du succès* (annale Rallye).","**1929** : titre de Lord Baden-Powell of Gilwell. **1939** : nommé pour le Nobel de la paix. **8 janvier 1941** : décès à Nyeri (Kenya), à 83 ans."],"src":"Bases du scoutisme.pdf, fiches-BP.pdf, Quiz-BP.pdf, Connaissance du mvt rallye dak23.pdf"},{"h":"Les 15 éléments fondamentaux","items":["**5 buts (acronyme SSSDF)** : Santé, Service du prochain, Sens de Dieu, Débrouillardise (sens du concret), Formation du caractère.","**5 dimensions** : la nature et le camp, la patrouille, la règle du jeu (la loi scoute), le civisme (la B.A.), l'engagement (la promesse).","**5 moteurs** : l'intérêt, l'action, les responsabilités, le système des patrouilles, la CDH et le CDC.","Nuance du texte : le « sens de Dieu » n'est pas en soi un but défini par B-P. Le but du scoutisme n'est pas de former de futurs prêtres, mais de bons citoyens."],"src":"Bases du scoutisme.pdf"},{"h":"Promesse, loi, devise, signes","items":["**Promesse** : triple engagement, être loyal, aider autrui, observer la loi scoute. Engagement volontaire, pris sur l'honneur devant ses frères.","**Loi** : des « conseils de vie » proposés, pas des interdictions. Pas de sanction : une discussion pour progresser. La loi de B-P compte 10 articles, plus un 11e non écrit : « le scout n'est pas un sot ».","**Devise « Sois prêt »** (Be Prepared), tirée des initiales de B-P. Trois qualités : le sens des autres, la compétence, l'observation suivie du réflexe.","**B.A.** : un service gratuit, jamais contre récompense. À la meute, un plaisir fait chaque jour ; à la troupe, un réflexe d'aider ; au clan, un service permanent.","**Signes** : salut de la main droite, trois doigts levés, pouce sur l'auriculaire ; poignée de main **gauche** (héritée des Ashantis) ; **fleur de lys** (indique le nord) ; trèfle pour les guides."],"src":"Bases du scoutisme.pdf, la devise, l'esprit et les éléments fondamentaux du scoutismes.docx, fiches-BP.pdf"},{"h":"Le scoutisme au Sénégal : les débuts","items":["**1931** : le R.P. Lecocq, curé de Dakar (Sacré-Cœur), veut créer des scouts. Naissance officieuse en décembre 1931, affiliation officielle en **1932** aux **Scouts de France**.","**8 mai 1932** : première promesse de quatre garçons, dans la cour de l'école Saint Michel (Dakar), fête de Sainte Jeanne d'Arc : Gabriel Sagna, Emmanuel Nunez, Georges Monteiro, Paul de Souza.","Première troupe : **Sainte Jeanne d'Arc**. Chef de troupe : Léon Fabert (jeune militaire du 6e RAC). Aumônier : R.P. Doutremepuich.","Deux premières patrouilles : **Rats palmistes** (CP Gabriel Sagna, SP Paul de Souza) et **Iguanes** (CP Emmanuel Nunez, SP Georges Monteiro).","Ensuite : une meute, puis les troupes René Caillé et Charles Foucault. Les scouts aînés deviennent routiers en **1938**."],"src":"Historique Scoutisme Senegal.pdf (Dakar Matin, 6 mai 1968)"},{"h":"Repères du Rallye et de la progression","items":["Saint patron des éclaireurs : **saint Georges, le 23 avril**.","**Carnet de preuves** : manuel-guide qui permet à l'éclaireur de progresser. 4 parties : **volontaire, engagé, technicien, animateur**.","Plus haute distinction : le **Loup de bronze**. Premier Sénégalais décoré : Albert Ndiaye (source unique, l'annale Rallye Dakar 2023, à confirmer)."],"src":"Connaissance du mvt rallye dak23.pdf, La Progression Personnelle.pdf, Livret Carnet de Preuves.pdf"}],"vigilance":["**Taille d'une patrouille** : huit dans *Bases du scoutisme* (récit des débuts), cinq à sept dans *LE SCOUTISME.docx* (dossier Troupe) et la fiche EDLN. À confirmer avec le Manuel du CP (décembre).","**Création de la Route** : 1918 selon l'annale Rallye, 1919 selon *Bases du scoutisme*. Date de *La route du succès* : 1922 (annale Rallye) ou 1919 (Bases du scoutisme).","**Âge des jeunes à Brownsea** : 9 à 17 ans (fiches-BP) contre 12 à 17 ans (Quiz-BP).","**Promesse de B-P** : le texte original parle de Dieu et du roi. Chaque association l'adapte (Dieu, l'Église et la Patrie dans la promesse de 1932 au Sénégal)."]}$xxb$::jsonb, now()),
  ('plan', $xxb${"cadence":["4 jours par semaine, 15 à 20 minutes : lire la fiche du mois, puis répondre aux cartes du jour.","1 quiz mixte par semaine (10 minutes) : le thème du mois et les anciens.","1 bilan en fin de mois : un mini-examen sur le thème, puis reprogrammation des points faibles.","Répétition espacée automatique : une carte réussie revient à J+1, J+3, J+7, J+21, puis J+60. Une carte ratée revient le lendemain."],"months":[{"n":1,"o":"Maîtriser les repères de B-P, les 15 éléments fondamentaux, la promesse, la loi, la devise et les débuts du scoutisme au Sénégal."},{"n":2,"o":"Connaître le cérémonial scout au Sénégal, la montée des couleurs et les objets et symboles protégés."},{"n":3,"o":"Comprendre la progression personnelle, le carnet de preuves, le rôle du CP et le fonctionnement des patrouilles."},{"n":4,"o":"Savoir ce que disent les statuts, le règlement intérieur et les procédures administratives et financières."},{"n":5,"o":"Maîtriser la responsabilité civile et pénale, les premiers secours et les règles de sécurité en camp."},{"n":6,"o":"Monter un projet de camp : fiche technique, déclaration, organisation et évaluation."},{"n":7,"o":"Planifier et animer une unité : réunions, techniques d'animation, pédagogie du jeu et du chant."},{"n":8,"o":"Connaître la Meute (louvetisme) et la Communauté (routiers) pour accompagner les passages entre branches."},{"n":9,"o":"Situer l'action locale dans les programmes de l'OMMS et l'éducation spirituelle des branches."},{"n":10,"o":"Consolider topographie et matelotage, et les bases de la gestion financière d'une unité."},{"n":11,"o":"S'entraîner sur les annales du Rallye, de 2015 à 2023."},{"n":12,"o":"Quiz mixte sur toute l'année et plan de rattrapage."}]}$xxb$::jsonb, now())
